create table if not exists public.hyperpop_sentinel_admins(account_id uuid primary key references public.hyperpop_accounts(id) on delete cascade,granted_at timestamptz not null default now(),granted_by text not null default 'system');
create table if not exists public.hyperpop_sentinel_devices(id uuid primary key default gen_random_uuid(),device_key text not null unique,first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),last_ip inet,user_agent text,created_at timestamptz not null default now());
create table if not exists public.hyperpop_sentinel_device_accounts(device_id uuid not null references public.hyperpop_sentinel_devices(id) on delete cascade,account_id uuid not null references public.hyperpop_accounts(id) on delete cascade,first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),primary key(device_id,account_id));
create table if not exists public.hyperpop_sentinel_bans(id uuid primary key default gen_random_uuid(),scope text not null check(scope in('account','device','network','account_device','full')),account_id uuid references public.hyperpop_accounts(id) on delete cascade,device_id uuid references public.hyperpop_sentinel_devices(id) on delete cascade,network_ip inet,reason text not null,duration text not null,starts_at timestamptz not null default now(),expires_at timestamptz,revoked_at timestamptz,revoked_by uuid references public.hyperpop_accounts(id),created_by uuid not null references public.hyperpop_accounts(id),created_at timestamptz not null default now(),check(account_id is not null or device_id is not null or network_ip is not null));
create index if not exists hyperpop_sentinel_bans_account_idx on public.hyperpop_sentinel_bans(account_id) where revoked_at is null;
create index if not exists hyperpop_sentinel_bans_device_idx on public.hyperpop_sentinel_bans(device_id) where revoked_at is null;
create table if not exists public.hyperpop_sentinel_appeals(id uuid primary key default gen_random_uuid(),ban_id uuid not null references public.hyperpop_sentinel_bans(id) on delete cascade,account_id uuid references public.hyperpop_accounts(id) on delete set null,message text not null,status text not null default 'pending' check(status in('pending','approved','denied')),reviewed_by uuid references public.hyperpop_accounts(id),reviewed_at timestamptz,review_note text,created_at timestamptz not null default now());
create table if not exists public.hyperpop_sentinel_events(id uuid primary key default gen_random_uuid(),actor_account_id uuid references public.hyperpop_accounts(id) on delete set null,event_type text not null,details jsonb not null default '{}'::jsonb,ip inet,created_at timestamptz not null default now());
alter table public.hyperpop_sentinel_admins enable row level security;alter table public.hyperpop_sentinel_devices enable row level security;alter table public.hyperpop_sentinel_device_accounts enable row level security;alter table public.hyperpop_sentinel_bans enable row level security;alter table public.hyperpop_sentinel_appeals enable row level security;alter table public.hyperpop_sentinel_events enable row level security;
revoke all on public.hyperpop_sentinel_admins,public.hyperpop_sentinel_devices,public.hyperpop_sentinel_device_accounts,public.hyperpop_sentinel_bans,public.hyperpop_sentinel_appeals,public.hyperpop_sentinel_events from anon,authenticated;
grant all on public.hyperpop_sentinel_admins,public.hyperpop_sentinel_devices,public.hyperpop_sentinel_device_accounts,public.hyperpop_sentinel_bans,public.hyperpop_sentinel_appeals,public.hyperpop_sentinel_events to service_role;
insert into public.hyperpop_sentinel_admins(account_id,granted_by) select id,'initial-sentinel-owner' from public.hyperpop_accounts where lower(username)=lower('Lyte3075') on conflict(account_id) do nothing;